import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec4 } from 'three/tsl';

export default async function createNode(config, ctx) {
  const { PlaneGeometry, Mesh, Group } = ctx.THREE;

  // Create group for the sprite
  const group = new Group();
  group.userData.cleanup = () => {
    // Dispose resources
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
  };

  // Atlas region: 512x320 pixels at (0,0) in 512x512 atlas
  const atlasWidth = 512;
  const atlasHeight = 512;
  const regionX = 0;
  const regionY = 0;
  const regionW = 512;
  const regionH = 320;

  // Aspect ratio of the region
  const aspectRatio = regionW / regionH; // 512/320 = 1.6

  // Create plane geometry: width scaled to aspect ratio, height = 1
  const planeWidth = aspectRatio;
  const planeHeight = 1;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  // Compute UV bounds for this atlas region
  const uvMinX = regionX / atlasWidth;
  const uvMaxX = (regionX + regionW) / atlasWidth;
  const uvMinY = 1 - (regionY + regionH) / atlasHeight; // Flip Y for typical image convention
  const uvMaxY = 1 - regionY / atlasHeight;

  // Update UVs to point to the atlas region
  const uvAttribute = geometry.attributes.uv;
  for (let i = 0; i < uvAttribute.count; i++) {
    let u = uvAttribute.getX(i);
    let v = uvAttribute.getY(i);

    // Remap [0,1] to atlas region
    u = uvMinX + u * (uvMaxX - uvMinX);
    v = uvMinY + v * (uvMaxY - uvMinY);

    uvAttribute.setXY(i, u, v);
  }
  uvAttribute.needsUpdate = true;

  // Load texture
  let texture = null;
  try {
    texture = await ctx.textureLoader.loadTexture(config.imageUrl);
    texture.colorSpace = 'srgb';
  } catch (err) {
    console.warn('Failed to load sprite texture:', err);
  }

  // Create material using TSL nodes
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: ctx.THREE.DoubleSide,
  });

  if (texture) {
    // Use the texture's UV node to sample the sprite
    material.colorNode = texture.getNode();
  } else {
    // Fallback: white if texture fails
    const fallbackColor = uv().mul(0).add(vec4(1, 1, 1, 1));
    material.colorNode = fallbackColor;
  }

  // Create mesh and add to group
  const mesh = new Mesh(geometry, material);
  mesh.position.copy(config.scenePosition || { x: 0, y: 0, z: 0 });
  if (config.sceneRotation) {
    mesh.rotation.order = 'YXZ';
    mesh.rotation.set(config.sceneRotation.x, config.sceneRotation.y, config.sceneRotation.z);
  }
  if (config.sceneScale) {
    mesh.scale.copy(config.sceneScale);
  }

  group.add(mesh);

  return group;
}
